using System;

public class Program
{
    public static void Main()
    {
        double total = 0;
        for (int i = 1; i <= 44; i++)
        {
            string name = Console.ReadLine();
            double len = double.Parse(Console.ReadLine());
            if (len > 10)
                Console.WriteLine(name);
            total += len;
        }
        Console.WriteLine(Math.Round(total, 2));
    }
}

